import pandas as pd, re, collections
df=pd.read_csv('dataset/data.csv', dtype=str, keep_default_na=False)
toks=collections.Counter()
for n in df.notes:
    for t in n.split(';'):
        toks[re.sub(r'\d','9',t.strip())]+=1
for k,v in toks.most_common(): print(repr(k),v)
print(collections.Counter(re.sub(r'\d','9',x) for x in df.event_time).most_common())
"
